<template><div class="page"><div class="page-header"><h2>归档记录</h2></div><el-card shadow="never" style="margin-bottom:16px"><div class="search-bar"><div class="field"><label>维护单号</label><el-input v-model="search.mid" placeholder="维护单号" size="small" style="width:160px" clearable @keyup.enter="doSearch"/></div><el-button type="primary" size="small" @click="doSearch" style="margin-left:auto">查询</el-button></div></el-card><el-card shadow="never"><el-table :data="items" v-loading="loading" stripe size="small"><el-table-column prop="maintenance_id" label="维护单号" width="120"/><el-table-column label="故障编码" width="100"><template #default="{row}">{{ row.fault_cd || '-' }}</template></el-table-column><el-table-column label="故障大类" width="100"><template #default="{row}">{{ row.fault_type || '-' }}</template></el-table-column><el-table-column label="故障小类" width="100"><template #default="{row}">{{ row.fault_detail_type || '-' }}</template></el-table-column><el-table-column prop="description" label="描述" min-width="160" show-overflow-tooltip/><el-table-column label="审核" width="70"><template #default="{row}"><el-tag :type="row.is_audit==='1'?'success':'warning'" size="small">{{ row.is_audit==='1'?'已审':'待审' }}</el-tag></template></el-table-column><el-table-column label="创建时间" width="110"><template #default="{row}">{{ row.create_time || '-' }}</template></el-table-column><el-table-column label="创建人" width="80"><template #default="{row}">{{ userName(row.creator) }}</template></el-table-column></el-table><AppPagination v-model:current-page="page" v-model:page-size="perPage" :total="total" style="margin-top:12px;justify-content:flex-end"/></el-card></div></template>
<script setup lang="ts">import {reactive} from 'vue';import AppPagination from '@/components/common/AppPagination.vue';import {useListPage} from '@/composables/useListPage';import {useUserNames} from '@/composables/useUserNames';import request from '@/api/request'
interface ArchiveRecord{[key:string]:unknown}
const search=reactive({mid:''})
const{items,loading,page,perPage,total,onSearch}=useListPage<ArchiveRecord>(async(p)=>{const mid=search.mid;if(mid){return request.get(`/itsm/archives/${mid}`).then((r:any)=>({data:{items:r.data?.archives||[],total:r.data?.archives?.length||0}}))};return{data:{items:[],total:0}}});const{userName}=useUserNames()
function doSearch(){page.value=1;load()}
</script>
<style scoped>.page{padding:0}.page-header{display:flex;justify-content:space-between;margin-bottom:16px}.page-header h2{font-size:18px;font-weight:600;margin:0}.search-bar{display:flex;gap:12px;align-items:center}.field{display:flex;align-items:center;gap:6px}.field label{font-size:13px;color:#606266}</style>
